CREATE TABLE IF NOT EXISTS `team_assignments` (`id` INT AUTO_INCREMENT PRIMARY KEY, `squad_id` INT NOT NULL, `challenge_id` INT NOT NULL, `due_at` DATE NULL, `created_by` INT NOT NULL, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `fk_team_assign_squad` FOREIGN KEY (`squad_id`) REFERENCES `squads` (`id`) ON DELETE CASCADE, CONSTRAINT `fk_team_assign_ch` FOREIGN KEY (`challenge_id`) REFERENCES `incident_challenges` (`id`) ON DELETE CASCADE, CONSTRAINT `fk_team_assign_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_team_assign_squad ON `team_assignments` (`squad_id`);
